SELECT carrier, DATE_FORMAT(shipped_date, 'yyyy-MM') AS shipped_month, ROUND(AVG(cost), 2) AS avg_cost, MAX(cost) AS max_cost, ROUND((100 * SUM(CASE WHEN carrier = 'UPS' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_ups FROM shipments WHERE cost >= 57 GROUP BY ROLLUP(carrier, DATE_FORMAT(shipped_date, 'yyyy-MM'));
